// shared evaluator + worker entry
const fs = require('fs');
const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');
const SIM = fs.readFileSync(__dirname + '/sim.js', 'utf8');
const mk = new Function(SIM + ';return rampartSimulate;');
const rampartSimulate = mk();

function stratFactory(tplPath, genome) {
  let src = fs.readFileSync(tplPath, 'utf8');
  src = src.replace(/\/\*G\*\/[\s\S]*?\/\*G\*\//, JSON.stringify(genome));
  return new Function(src + ';return createStrategy;')();
}
function evalGenome(tplPath, genome, seeds, maxTicks) {
  const cs = stratFactory(tplPath, genome);
  const res = [];
  for (const s of seeds) res.push(rampartSimulate(cs, s, maxTicks || 12020).score);
  return res;
}
module.exports = { evalGenome, stratFactory, rampartSimulate };

if (!isMainThread) {
  parentPort.on('message', (m) => {
    const t0 = Date.now();
    const r = evalGenome(m.tpl, m.genome, m.seeds, m.maxTicks);
    parentPort.postMessage({ id: m.id, scores: r, ms: Date.now() - t0 });
  });
}

