const { Worker } = require('worker_threads');
const fs = require('fs');
const path = require('path');
const TPL = process.argv[2] || path.join(__dirname, 'strat_t.js');
const OUT = process.argv[3] || path.join(__dirname, 'best.json');
const GENS = +(process.argv[4] || 2000);
const NSEED = +(process.argv[5] || 48);
const LAMBDA = +(process.argv[6] || 40);
const INIT = process.argv[7];
const NW = 10;
let rs = (+process.env.RS || 1) * 2654435761 >>> 0;
function rnd() { rs = (rs + 0x6D2B79F5) | 0; let t = Math.imul(rs ^ (rs >>> 15), 1 | rs); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }
const ri = (n) => Math.floor(rnd() * n);

const workers = [], free = [], waiting = [];
for (let i = 0; i < NW; i++) {
  const w = new Worker(path.join(__dirname, 'evalw.js'));
  w.on('message', (m) => { const cb = w.cb; w.cb = null; free.push(w); pump(); cb(m); });
  workers.push(w); free.push(w);
}
function pump() { while (free.length && waiting.length) { const w = free.pop(); const j = waiting.shift(); w.cb = j.cb; w.postMessage(j.msg); } }
let jid = 0;
function evalAsync(genome, seeds) { return new Promise((res) => { waiting.push({ msg: { id: jid++, tpl: TPL, genome, seeds }, cb: (m) => res(m.scores) }); pump(); }); }
const mean = (a) => a.reduce((x, y) => x + y, 0) / a.length;

const NSLOT = 16;
function randStep() { return [ri(NSLOT), ri(5), 1 + ri(3)]; }
function clone(g) { return JSON.parse(JSON.stringify(g)); }
function mutate(g) {
  g = clone(g);
  const n = 1 + (rnd() < 0.4 ? 1 : 0) + (rnd() < 0.2 ? 2 : 0);
  for (let m = 0; m < n; m++) {
    const r = rnd(), S = g.steps;
    if (r < 0.14 && S.length > 2) { const i = ri(S.length), j = ri(S.length); const t = S[i]; S[i] = S[j]; S[j] = t; }
    else if (r < 0.28 && S.length > 2) { const i = ri(S.length); const s = S.splice(i, 1)[0]; S.splice(ri(S.length + 1), 0, s); }
    else if (r < 0.40) { S[ri(S.length)][0] = ri(NSLOT); }
    else if (r < 0.54) { S[ri(S.length)][1] = ri(5); }
    else if (r < 0.64) { S[ri(S.length)][2] = 1 + ri(3); }
    else if (r < 0.76 && S.length < 70) { S.splice(ri(S.length + 1), 0, randStep()); }
    else if (r < 0.86 && S.length > 4) { S.splice(ri(S.length), 1); }
    else if (r < 0.94) { g.tm[ri(5)] = ri(11); }
    else { g.look = 1 + ri(4); }
  }
  return g;
}
function normalize(g) { return g; }

(async () => {
  let best;
  if (INIT && fs.existsSync(INIT)) best = JSON.parse(fs.readFileSync(INIT, 'utf8'));
  else {
    best = { steps: [], tm: [0, 0, 0, 0, 0], look: 1 };
    const types = [3, 3, 2, 0, 1, 4];
    for (let i = 0; i < 16; i++) best.steps.push([i, types[i % types.length], 1]);
    for (let i = 0; i < 16; i++) best.steps.push([i, best.steps[i][1], 2]);
  }
  let seedBase = 5000;
  const mkSeeds = () => { const a = []; for (let i = 0; i < NSEED; i++) a.push(seedBase + i); return a; };
  let seeds = mkSeeds();
  let bestScore = mean(await evalAsync(best, seeds));
  console.log('init', bestScore.toFixed(3));
  const t0 = Date.now();
  for (let gen = 1; gen <= GENS; gen++) {
    if (gen % 40 === 0) { seedBase += NSEED; seeds = mkSeeds(); bestScore = mean(await evalAsync(best, seeds)); }
    const kids = []; for (let i = 0; i < LAMBDA; i++) kids.push(mutate(rnd() < 0.7 ? best : (kids[ri(kids.length || 1)] || best)));
    const scores = await Promise.all(kids.map((k) => evalAsync(k, seeds).then(mean)));
    let bi = -1, bsx = bestScore;
    for (let i = 0; i < kids.length; i++) if (scores[i] >= bsx) { bsx = scores[i]; bi = i; }
    if (bi >= 0) { best = kids[bi]; bestScore = bsx; }
    if (gen % 20 === 0) {
      fs.writeFileSync(OUT, JSON.stringify(best));
      console.log('gen', gen, bestScore.toFixed(3), 'steps', best.steps.length, ((Date.now() - t0) / 1000).toFixed(0) + 's');
    }
  }
  fs.writeFileSync(OUT, JSON.stringify(best));
  console.log('done', JSON.stringify(best));
  process.exit(0);
})();

