    if (p >= route.len) { var e = segs[segs.length - 1]; return [e.x1, e.y1]; }
    for (var i = 0; i < segs.length; i++) {
      var s = segs[i];
      if (p < s.s + s.l) {
        var d = p - s.s;
        return [s.x0 + (s.x1 > s.x0 ? d : s.x1 < s.x0 ? -d : 0), s.y0 + (s.y1 > s.y0 ? d : s.y1 < s.y0 ? -d : 0)];
      }
    }
    return [segs[0].x0, segs[0].y0];
  }
  var TT = {
    bolt:   { cost: 50,  dmg: 26,  per: 8,  range: 300, splash: 0,  slow: 0,  pierce: false, ground: true,  air: true,  idx: 0 },
    cannon: { cost: 90,  dmg: 60,  per: 24, range: 260, splash: 90, slow: 0,  pierce: false, ground: true,  air: false, idx: 1 },
    frost:  { cost: 70,  dmg: 10,  per: 12, range: 240, splash: 0,  slow: 30, pierce: false, ground: true,  air: true,  idx: 2 },
    lance:  { cost: 120, dmg: 180, per: 36, range: 360, splash: 0,  slow: 0,  pierce: true,  ground: true,  air: false, idx: 3 },
    flak:   { cost: 80,  dmg: 40,  per: 10, range: 320, splash: 70, slow: 0,  pierce: false, ground: false, air: true,  idx: 4 }
  };
  var ET = {
    grunt:     { hp: 60,  speed: 10, bounty: 4, leak: 1, air: 0, first: 1, weight: 10 },
    runner:    { hp: 40,  speed: 20, bounty: 4, leak: 1, air: 0, first: 2, weight: 4 },
    wisp:      { hp: 50,  speed: 12, bounty: 6, leak: 2, air: 1, first: 3, weight: 3 },
    brute:     { hp: 150, speed: 6,  bounty: 9, leak: 3, air: 0, first: 4, weight: 3 },
    splitter:  { hp: 90,  speed: 8,  bounty: 6, leak: 2, air: 0, first: 6, weight: 2 },
    mender:    { hp: 70,  speed: 8,  bounty: 7, leak: 2, air: 0, first: 8, weight: 1 },
    splitling: { hp: 1,   speed: 12, bounty: 1, leak: 1, air: 0, first: 99, weight: 0 }
  };
  var ORDER = ['grunt', 'runner', 'wisp', 'brute', 'splitter', 'mender'];
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }
  var rng = mulberry32(seed);
  var waves = [];
  function genWave(w) {
    var types = [], sum = 0, i;
    for (i = 0; i < ORDER.length; i++) if (ET[ORDER[i]].first <= w) { types.push(ORDER[i]); sum += ET[ORDER[i]].weight; }
    var n = 4 + Math.floor(3 * w / 5), out = [];
    for (i = 0; i < n; i++) {
      var r = rng() % sum;
      for (var j = 0; j < types.length; j++) {
        var wt = ET[types[j]].weight;
        if (r < wt) { out.push(types[j]); break; }
        r -= wt;
      }
    }
    waves[w] = out;
  }
  var mult = [0, 1000];
  function mOf(w) { while (mult.length <= w) mult.push(Math.floor(mult[mult.length - 1] * 108 / 100)); return mult[w]; }

  var strat = createStrategy();
  var log = [];
  var gold = 250, baseHp = 10, tick = 0;
  var slots = [];
  for (var si = 0; si < 16; si++) slots.push(null);
  var enemies = []; // ascending id
  var nextId = 1;
  var queue = []; // spawn queue {tick, wave, idx, type}
  var fallTick = -1;
  genWave(1);

  function dmgOf(t, tier) { var d = TT[t].dmg; for (var i = 1; i < tier; i++) d = Math.floor(d * 16 / 10); return d; }
  function rangeOf(t, tier) { return TT[t].range + 30 * (tier - 1); }
  function armorOf(e) {
    if (e.type === 'grunt') return Math.floor(e.wave / 4);
    if (e.type === 'brute') return 6 + e.wave;
    return 0;
  }
  function effSpeed(e) { return e.slow > 0 ? Math.floor(e.speed * 60 / 100) : e.speed; }
  function view(e) {
    return { id: e.id, type: e.type, hp: e.hp, maxHp: e.maxHp, x: e.x, y: e.y, air: e.air, armor: armorOf(e), speed: e.speed, slowed: e.slow, remaining: ROUTES[e.air].len - e.progress };
  }
  function setPos(e) { var p = posOf(ROUTES[e.air], e.progress); e.x = p[0]; e.y = p[1]; }
  function mkEnemy(type, wave, maxHp, progress) {
    var d = ET[type];
    var e = { id: nextId++, type: type, wave: wave, maxHp: maxHp, hp: maxHp, speed: d.speed, air: d.air, progress: progress, age: 0, slow: 0, x: 0, y: 0 };
    setPos(e);
    return e;
  }
  function insertEnemy(e) { enemies.push(e); } // ids ascending since nextId increments

  function applyActions(acts) {
    if (!Array.isArray(acts)) return;
    var n = Math.min(32, acts.length);
    for (var i = 0; i < n; i++) {
      var a = acts[i];
      if (!a || typeof a !== 'object') continue;
      var s = a.slot;
      if (typeof s !== 'number' || s !== Math.floor(s) || s < 0 || s > 15) continue;
      if (a.op === 'build') {
        var t = TT[a.type];
        if (!t || !Object.prototype.hasOwnProperty.call(TT, a.type)) continue;
        if (slots[s] || gold < t.cost) continue;
        gold -= t.cost;
        slots[s] = { type: a.type, tier: 1, spent: t.cost, cd: 0, slot: s };
        log.push([tick, 'B', s, t.idx]);
      } else if (a.op === 'upgrade') {
        var tr = slots[s];
        if (!tr || tr.tier >= 3) continue;
        var c = TT[tr.type].cost * (tr.tier === 1 ? 1 : 2);
        if (gold < c) continue;
        gold -= c; tr.spent += c; tr.tier++;
        log.push([tick, 'U', s, tr.tier]);
      } else if (a.op === 'sell') {
        var ts = slots[s];
        if (!ts) continue;
        gold += Math.floor(ts.spent * 70 / 100);
        slots[s] = null;
        log.push([tick, 'S', s, 0]);
      }
    }
  }

  function snapshot(w) {
    var sl = [];
    for (var i = 0; i < 16; i++) {
      var tr = slots[i];
      sl.push({ slot: i, x: SLOTS[i][0], y: SLOTS[i][1], turret: tr ? { type: tr.type, tier: tr.tier, spent: tr.spent } : null });
    }
    var ev = [];
    for (var j = 0; j < enemies.length; j++) ev.push(view(enemies[j]));
    return { tick: tick, wave: w, gold: gold, baseHp: baseHp, slots: sl, enemies: ev, nextWave: waves[w + 1].slice() };
  }

  function killEnemy(e, slot) {
    gold += ET[e.type].bounty;
    log.push([tick, 'K', e.id, slot]);
    var kids = null;
    if (e.type === 'splitter') {
      var hp = Math.max(1, Math.floor(e.maxHp / 4));
      kids = [];
      for (var k = 0; k < 3; k++) { var c = mkEnemy('splitling', e.wave, hp, e.progress); insertEnemy(c); kids.push(c.id); }
    }
    if (rec) rec.kill(tick, e, slot, kids);
  }

  var endTick = maxTicks;
  for (tick = 0; tick < maxTicks; tick++) {
    // 1 wave start
    if (tick >= 20 && (tick - 20) % 40 === 0) {
      var w = (tick - 20) / 40 + 1;
      gold += Math.min(50, Math.floor(gold * 5 / 100)) + 10 + 2 * w;
      genWave(w + 1);
      var acts;
      try { acts = strat.plan(snapshot(w)); } catch (err) { acts = []; }
      applyActions(acts);
      var wv = waves[w];
      for (var qi = 0; qi < wv.length; qi++) queue.push({ tick: tick + 4 * qi, wave: w, idx: qi, type: wv[qi] });
      queue.sort(function (a, b) { return a.tick - b.tick || a.wave - b.wave || a.idx - b.idx; });
    }
    // 2 spawn
    while (queue.length && queue[0].tick <= tick) {
      var q = queue.shift();
      var d = ET[q.type];
      insertEnemy(mkEnemy(q.type, q.wave, Math.floor(d.hp * mOf(q.wave) / 1000), 0));
    }
    // 3 move
    var fell = false;
    for (var i = 0; i < enemies.length; i++) {
      var e = enemies[i];
      e.progress += effSpeed(e);
      if (e.progress >= ROUTES[e.air].len) {
        baseHp -= ET[e.type].leak;
        e.dead = true;
        log.push([tick, 'L', e.id, baseHp]);
        if (rec) rec.leak(tick, e, baseHp);
        if (baseHp <= 0) { fell = true; break; }
      } else setPos(e);
    }
    if (fell) {
      var cw = Math.floor((tick - 20) / 40) + 1;
      log.push([tick, 'F', cw, 0]);
      if (rec) rec.fall(tick, cw, gold, baseHp, enemies, slots);
      fallTick = tick; endTick = tick;
      break;
    }
    enemies = enemies.filter(function (x) { return !x.dead; });
    // 4 age & heal
    for (i = 0; i < enemies.length; i++) {
      e = enemies[i];
      e.age++;
      if (e.type === 'mender' && e.age % 20 === 0) {
        for (var j = 0; j < enemies.length; j++) {
          var o = enemies[j], dx = o.x - e.x, dy = o.y - e.y;
          if (dx * dx + dy * dy <= 150 * 150) o.hp = Math.min(o.maxHp, o.hp + Math.floor(o.maxHp * 8 / 100));
        }
        if (rec) rec.heal(tick, e);
      }
    }
    // 5 turrets
    for (var s = 0; s < 16; s++) {
      var tr = slots[s];
      if (!tr) continue;
      if (tr.cd > 0) tr.cd--;
      if (tr.cd > 0) continue;
      var T = TT[tr.type], rng2 = rangeOf(tr.type, tr.tier), r2 = rng2 * rng2;
      var tx = SLOTS[s][0] * 100 + 50, ty = SLOTS[s][1] * 100 + 50;
      var cands = [];
      for (i = 0; i < enemies.length; i++) {
        e = enemies[i];
        if (e.hp <= 0) continue;
        if (e.air ? !T.air : !T.ground) continue;
        var ddx = e.x - tx, ddy = e.y - ty;
        if (ddx * ddx + ddy * ddy <= r2) cands.push(e);
      }
      if (!cands.length) continue;
      var tgt = null;
      if (typeof strat.target === 'function') {
        var views = cands.map(view);
        var id;
        try { id = strat.target({ slot: s, type: tr.type, tier: tr.tier, x: tx, y: ty, range: rng2 }, views); } catch (err) { id = null; }
        for (i = 0; i < cands.length; i++) if (cands[i].id === id) { tgt = cands[i]; break; }
      }
      if (!tgt) {
        tgt = cands[0];
        var br = ROUTES[tgt.air].len - tgt.progress;
        for (i = 1; i < cands.length; i++) {
          var rm = ROUTES[cands[i].air].len - cands[i].progress;
          if (rm < br) { br = rm; tgt = cands[i]; }
        }
      }
      var dmg = dmgOf(tr.type, tr.tier);
      var hit = [tgt];
      if (T.splash > 0) {
        hit = [];
        var sr = T.splash * T.splash;
        for (i = 0; i < enemies.length; i++) {
          e = enemies[i];
          if (e.hp <= 0) continue;
          if (e.air ? !T.air : !T.ground) continue;
          var sx = e.x - tgt.x, sy = e.y - tgt.y;
          if (sx * sx + sy * sy <= sr) hit.push(e);
        }
      }
      for (i = 0; i < hit.length; i++) {
        e = hit[i];
        var dd = T.pierce ? dmg : Math.max(1, dmg - armorOf(e));
        e.hp -= dd;
        if (T.slow) e.slow = T.slow;
      }
      tr.cd = T.per;
      if (rec) rec.shot(tick, s, tr, tgt, hit);
      // removal; splitlings appended with higher ids -> still ascending
      var cur = enemies.slice();
      var alive = [];
      for (i = 0; i < cur.length; i++) {
        e = cur[i];
        if (e.hp <= 0) killEnemy(e, s); else alive.push(e);
      }
      // newly spawned splitlings are in enemies (pushed during killEnemy)
      var added = enemies.slice(cur.length);
      enemies = alive.concat(added);
    }
    // 6 slow
    for (i = 0; i < enemies.length; i++) if (enemies[i].slow > 0) enemies[i].slow--;
    if (rec) rec.tick(tick, enemies, slots, gold, baseHp);
  }
  var hash = 0x811c9dc5, js = JSON.stringify(log);
  for (var h = 0; h < js.length; h++) { hash ^= js.charCodeAt(h); hash = Math.imul(hash, 0x01000193); }
  hash = (hash >>> 0).toString(16);
  while (hash.length < 8) hash = '0' + hash;
  var score = Math.round(((endTick - 20) / 40) * 100) / 100;
  return { score: score, fallTick: fallTick, log: log, hash: hash };
}

