// Electron harness: node-style script run as the app. usage: Antigravity shot/ <html> <out.png> [js-to-eval-before] [waitMs]
const { app, BrowserWindow } = require('electron');
const fs = require('fs');
const args = process.argv.slice(2).filter((a) => !a.startsWith('--'));
const htmlPath = args[0], out = args[1], script = args[2] || '', waitMs = +(args[3] || 2500);
const W = +(process.env.W || 1280), H = +(process.env.H || 720);
app.disableHardwareAcceleration && 0;
app.commandLine.appendSwitch('ignore-gpu-blocklist');
app.commandLine.appendSwitch('enable-unsafe-swiftshader');
app.whenReady().then(async () => {
  const win = new BrowserWindow({ width: W, height: H, show: true, useContentSize: true, webPreferences: { contextIsolation: false, backgroundThrottling: false } });
  const logs = [];
  win.webContents.on('console-message', (e, level, msg, line, src) => { console.log('[page]', level, msg, src ? src.split('/').pop() + ':' + line : ''); });
  win.webContents.on('render-process-gone', (e, d) => console.log('gone', JSON.stringify(d)));
  await win.loadURL('file://' + htmlPath);
  await new Promise((r) => setTimeout(r, 800));
  if (script) {
    const steps = script.split('|||');
    for (const st of steps) {
      const m = st.match(/^wait:(\d+)$/);
      if (m) { await new Promise((r) => setTimeout(r, +m[1])); continue; }
      const m2 = st.match(/^shot:(.+)$/);
      if (m2) { const img = await win.webContents.capturePage(); fs.writeFileSync(m2[1], img.toPNG()); continue; }
      try { const r = await win.webContents.executeJavaScript(st); if (r !== undefined) console.log('[eval]', JSON.stringify(r)); } catch (e) { console.log('[evalerr]', String(e)); }
    }
  }
  await new Promise((r) => setTimeout(r, waitMs));
  const img = await win.webContents.capturePage();
  fs.writeFileSync(out, img.toPNG());
  console.log('saved', out, img.getSize().width, img.getSize().height);
  app.quit();
});

