/* ===================== Replay data (built from rampart-sim) ===================== */
const DURATION = 100;
const TPS = 20;
const REPLAY_SEED = 42;
const REPLAY_TICKS = 2020;
const TYPE_NAMES = ['grunt', 'runner', 'wisp', 'brute', 'splitter', 'mender', 'splitling'];
const TYPE_IDX = { grunt: 0, runner: 1, wisp: 2, brute: 3, splitter: 4, mender: 5, splitling: 6 };
const TUR_NAMES = ['bolt', 'cannon', 'frost', 'lance', 'flak'];
const TUR_IDX = { bolt: 0, cannon: 1, frost: 2, lance: 3, flak: 4 };
const TUR_SPLASH = [0, 0.9, 0, 0, 0.7];
const SLOT_TILES = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
const GROUND_PTS = [[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]];
const AIR_PTS = [[0,6],[21,6],[21,11],[23,11]];

function makeRoute(pts) {
  const segs = []; let len = 0;
  for (let i = 0; i + 1 < pts.length; i++) {
    const x0 = pts[i][0] * 100 + 50, y0 = pts[i][1] * 100 + 50, x1 = pts[i + 1][0] * 100 + 50, y1 = pts[i + 1][1] * 100 + 50;
    const l = Math.abs(x1 - x0) + Math.abs(y1 - y0);
    segs.push({ x0, y0, x1, y1, l, s: len, dx: Math.sign(x1 - x0), dy: Math.sign(y1 - y0) });
    len += l;
  }
  return { segs, len };
}
const ROUTES = [makeRoute(GROUND_PTS), makeRoute(AIR_PTS)];
const _pp = [0, 0, 0, 0];
// position (centi-tiles) and heading (unit dir) at distance p along route r -> _pp = [x, y, dx, dy]
function routeAt(r, p) {
  const R = ROUTES[r], S = R.segs;
  if (p < 0) p = 0;
  let sg = S[S.length - 1];
  for (let i = 0; i < S.length; i++) if (p < S[i].s + S[i].l) { sg = S[i]; break; }
  let d = p - sg.s; if (d > sg.l) d = sg.l;
  _pp[0] = sg.x0 + sg.dx * d; _pp[1] = sg.y0 + sg.dy * d; _pp[2] = sg.dx; _pp[3] = sg.dy;
  return _pp;
}

// seeded visual RNG (never Math.random)
function mulberryF(a) { return function () { a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
const vrand = mulberryF(42);

function waveStartTick(w) { return 20 + 40 * (w - 1); }
function waveAtTick(t) { return t < 20 ? 0 : Math.floor((t - 20) / 40) + 1; }

function buildReplay() {
  const R = { frames: new Array(REPLAY_TICKS), last: -1, shots: [], kills: [], leaks: [], heals: [], waves: [], fall: null, res: null, ops: [] };
  const counts = (arr) => { const c = [0, 0, 0, 0, 0, 0]; for (const t of arr) c[TYPE_IDX[t]]++; return c; };
  const snap = (tick, en, sl, gold, baseHp) => {
    let n = 0; for (let i = 0; i < en.length; i++) if (!en[i].dead) n++;
    const f = { tick, n, id: new Int32Array(n), ty: new Uint8Array(n), pr: new Float32Array(n), hp: new Float32Array(n), sw: new Uint8Array(n), tur: new Uint8Array(16), gold, baseHp, nxt: null };
    let j = 0;
    for (let i = 0; i < en.length; i++) {
      const e = en[i]; if (e.dead) continue;
      f.id[j] = e.id; f.ty[j] = TYPE_IDX[e.type]; f.pr[j] = e.progress; f.hp[j] = Math.max(0, e.hp) / e.maxHp; f.sw[j] = e.slow > 0 ? 1 : 0; j++;
    }
