/* ===================== geometry helpers ===================== */
function mergeParts(parts) {
  const pos = [], nor = [], col = [];
  const m = new THREE.Matrix4(), q = new THREE.Quaternion(), eu = new THREE.Euler();
  for (const p of parts) {
    const g = p.g.index ? p.g.toNonIndexed() : p.g.clone();
    const r = p.r || [0, 0, 0], ps = p.p || [0, 0, 0], sc = p.s || [1, 1, 1];
    eu.set(r[0], r[1], r[2]); q.setFromEuler(eu);
    m.compose(new THREE.Vector3(ps[0], ps[1], ps[2]), q, new THREE.Vector3(sc[0], sc[1], sc[2]));
    g.applyMatrix4(m);
    const c = new THREE.Color(p.c);
    const P = g.attributes.position.array, N = g.attributes.normal.array;
    for (let i = 0; i < P.length; i += 3) { pos.push(P[i], P[i + 1], P[i + 2]); nor.push(N[i], N[i + 1], N[i + 2]); col.push(c.r, c.g, c.b); }
    g.dispose();
