}
const box = (w, h, d) => new THREE.BoxGeometry(w, h, d);
const cyl = (rt, rb, h, s) => new THREE.CylinderGeometry(rt, rb, h, s || 12);
const sph = (r, w, h) => new THREE.SphereGeometry(r, w || 12, h || 8);
const cone = (r, h, s) => new THREE.ConeGeometry(r, h, s || 10);
const oct = (r) => new THREE.OctahedronGeometry(r, 0);
