const sstep = (a, b, x) => { const t = Math.max(0, Math.min(1, (x - a) / (b - a))); return t * t * (3 - 2 * t); };
function terrainH(x, z) {
  const dr = distPath(x, z, GROUND_PTS), dp = distPads(x, z);
  const flat = sstep(0.55, 1.3, dr) * sstep(0.55, 1.1, dp);
  const kd = Math.hypot(x - 23.5, z - 11.5);
  const k = flat * sstep(1.2, 2.2, kd);
  const out = Math.max(0, Math.max(-x, x - 24, -z, z - 14));
  const n = vnoise(x * 0.9, z * 0.9) * 0.16 + vnoise(x * 2.3 + 9, z * 2.3 + 4) * 0.06;
  return k * (n + sstep(0, 1.8, out) * 0.5 * (0.6 + vnoise(x * 0.5, z * 0.5)));
}

/* ===================== world ===================== */
const world = new THREE.Group(); scene.add(world);
(function buildTerrain() {
  const X0 = -3, X1 = 27, Z0 = -3, Z1 = 17, SUB = 5;
  const nx = (X1 - X0) * SUB, nz = (Z1 - Z0) * SUB;
  const geo = new THREE.PlaneGeometry(X1 - X0, Z1 - Z0, nx, nz);
  geo.rotateX(-Math.PI / 2);
  const P = geo.attributes.position; const cols = new Float32Array(P.count * 3);
  const c = new THREE.Color();
  for (let i = 0; i < P.count; i++) {
    const x = P.getX(i) + (X0 + X1) / 2, z = P.getZ(i) + (Z0 + Z1) / 2;
    P.setX(i, x); P.setZ(i, z);
    const h = terrainH(x, z); P.setY(i, h);
    const dr = distPath(x, z, GROUND_PTS);
    const n1 = vnoise(x * 3.1, z * 3.1), n2 = vnoise(x * 0.7 + 3, z * 0.7 + 8);
    if (dr < 0.42) { const v = 0.19 + n1 * 0.07 + (hash2(Math.floor(x * 5), Math.floor(z * 5)) - 0.5) * 0.05; c.setRGB(v * 0.95, v, v * 1.12); }
    else if (dr < 0.56) { const v = 0.30 + n1 * 0.07; c.setRGB(v, v * 0.98, v * 0.95); }
