(function buildRoadDetail() {
  // edge stones along the road
  const geo = box(0.16, 0.1, 0.22); const mat = stdMat({ color: 0x5a5a63, roughness: 0.9 });
  const items = [];
  for (let i = 0; i + 1 < GROUND_PTS.length; i++) {
    const ax = GROUND_PTS[i][0] + 0.5, az = GROUND_PTS[i][1] + 0.5, bx = GROUND_PTS[i + 1][0] + 0.5, bz = GROUND_PTS[i + 1][1] + 0.5;
    const len = Math.abs(bx - ax) + Math.abs(bz - az), dx = Math.sign(bx - ax), dz = Math.sign(bz - az);
    for (let s = 0.2; s < len; s += 0.55) for (const side of [-1, 1]) {
      const jitter = (vrand() - 0.5) * 0.06;
      const px = ax + dx * s + (-dz) * side * (0.5 + jitter), pz = az + dz * s + dx * side * (0.5 + jitter);
      items.push([px, pz, dx !== 0 ? 0 : Math.PI / 2, 0.8 + vrand() * 0.5]);
