  const treeG = mergeParts([{ g: cyl(0.05, 0.07, 0.3, 6), c: 0x4a3524, p: [0, 0.15, 0] }, { g: cone(0.3, 0.55, 7), c: 0x2d4a33, p: [0, 0.5, 0] }, { g: cone(0.22, 0.45, 7), c: 0x365c3d, p: [0, 0.8, 0] }]);
