    if (distPath(x, z, AIR_PTS) < 0.3) continue;
    if (rocks.length < 70 && (trees.length >= 90 || vrand() < 0.4)) rocks.push([x, z, 0.12 + vrand() * 0.2, vrand() * 6.28]);
