const padMeshes = SLOT_TILES.map((t) => { const m = new THREE.Mesh(padGeo, padMat); m.position.set(t[0] + 0.5, 0, t[1] + 0.5); m.castShadow = true; m.receiveShadow = true; world.add(m); return m; });

