  function mkRoute(pts) {
    var segs = [], len = 0;
    for (var i = 0; i + 1 < pts.length; i++) {
      var x0 = pts[i][0] * 100 + 50, y0 = pts[i][1] * 100 + 50, x1 = pts[i + 1][0] * 100 + 50, y1 = pts[i + 1][1] * 100 + 50;
