  for (let i = 0; i < 14; i++) { const a = vrand() * 6.283, sp = 0.6 + vrand() * 1.6; l.deb.push([Math.cos(a) * sp, 1.6 + vrand() * 2, Math.sin(a) * sp, vrand() * 6, 0.07 + vrand() * 0.1]); }
