for (let i = 0; i < 90; i++) { const a = vrand() * 6.283, sp = 1.2 + vrand() * 4.2; REP.fallDeb.push([Math.cos(a) * sp, 3 + vrand() * 5, Math.sin(a) * sp, vrand() * 6, 0.1 + vrand() * 0.2, vrand()]); }
