/* ===================== Renderer, camera, lights ===================== */
const canvas = document.getElementById('stage');
const renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true, alpha: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
renderer.setSize(window.innerWidth, window.innerHeight, false);
renderer.outputEncoding = THREE.sRGBEncoding;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.15;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.setClearColor(0x000000, 0);
renderer.autoClear = false;

const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(34, 16 / 9, 0.1, 500);
const CAM_TARGET = new THREE.Vector3(12, 0, 7);
const camBase = new THREE.Vector3();
const U_DESAT = { value: 1 };
const U_TIME = { value: 0 };

function patchDesat(mat) {
  mat.onBeforeCompile = function (shader) {
    shader.uniforms.uDesat = U_DESAT;
    shader.fragmentShader = 'uniform float uDesat;\n' + shader.fragmentShader.replace('#include <dithering_fragment>',
      'gl_FragColor.rgb = mix(vec3(dot(gl_FragColor.rgb, vec3(0.299, 0.587, 0.114))), gl_FragColor.rgb, uDesat);\n#include <dithering_fragment>');
  };
  return mat;
}
const stdMat = (o) => patchDesat(new THREE.MeshStandardMaterial(o));
const basicMat = (o) => patchDesat(new THREE.MeshBasicMaterial(o));

function frameCamera(w, h) {
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
  const pitch = 55 * Math.PI / 180;
  const corners = [[-0.5, -0.5], [24.5, -0.5], [-0.5, 14.5], [24.5, 14.5]];
  const bottomReserve = 2 * 96 / h;     // NDC height of the dock band
  const availH = (2 - bottomReserve) * 0.985, availW = 2 * 0.985;
  const v = new THREE.Vector3();
  function measure(d) {
    camera.position.set(CAM_TARGET.x, CAM_TARGET.y + Math.sin(pitch) * d, CAM_TARGET.z + Math.cos(pitch) * d);
    camera.lookAt(CAM_TARGET);
    camera.updateMatrixWorld(true);
    let x0 = 9, x1 = -9, y0 = 9, y1 = -9;
    for (const c of corners) { v.set(c[0], 0, c[1]).project(camera); x0 = Math.min(x0, v.x); x1 = Math.max(x1, v.x); y0 = Math.min(y0, v.y); y1 = Math.max(y1, v.y); }
    return { w: x1 - x0, h: y1 - y0, cy: (y0 + y1) / 2 };
  }
  let lo = 4, hi = 300;
  for (let i = 0; i < 50; i++) { const mid = (lo + hi) / 2, m = measure(mid); if (m.w <= availW && m.h <= availH) hi = mid; else lo = mid; }
  const m = measure(hi);
  camBase.copy(camera.position);
  const wantCy = bottomReserve / 2;      // centre of the free band
  camera.projectionMatrix.elements[9] = -(wantCy - m.cy);
  camera.projectionMatrixInverse.copy(camera.projectionMatrix).invert();
}

scene.add(new THREE.HemisphereLight(0x93a0d8, 0x40322c, 0.62));
const sun = new THREE.DirectionalLight(0xffb774, 1.55);
sun.position.set(-8, 16, 20);
sun.target.position.set(12, 0, 7);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.left = -17; sun.shadow.camera.right = 17; sun.shadow.camera.top = 15; sun.shadow.camera.bottom = -15;
sun.shadow.camera.near = 1; sun.shadow.camera.far = 70;
sun.shadow.bias = -0.0006;
scene.add(sun); scene.add(sun.target);
const fill = new THREE.DirectionalLight(0x6d82d6, 0.35);
fill.position.set(18, 10, -8); fill.target.position.set(12, 0, 7);
scene.add(fill); scene.add(fill.target);

/* ===================== geometry helpers ===================== */
function mergeParts(parts) {
  const pos = [], nor = [], col = [];
  const m = new THREE.Matrix4(), q = new THREE.Quaternion(), eu = new THREE.Euler();
