(function buildTerrain() {
  const X0 = -3, X1 = 27, Z0 = -3, Z1 = 17, SUB = 5;
  const nx = (X1 - X0) * SUB, nz = (Z1 - Z0) * SUB;
  const geo = new THREE.PlaneGeometry(X1 - X0, Z1 - Z0, nx, nz);
  geo.rotateX(-Math.PI / 2);
  const P = geo.attributes.position; const cols = new Float32Array(P.count * 3);
  const c = new THREE.Color();
  for (let i = 0; i < P.count; i++) {
    const x = P.getX(i) + (X0 + X1) / 2, z = P.getZ(i) + (Z0 + Z1) / 2;
    P.setX(i, x); P.setZ(i, z);
    const h = terrainH(x, z); P.setY(i, h);
    const dr = distPath(x, z, GROUND_PTS);
    const n1 = vnoise(x * 3.1, z * 3.1), n2 = vnoise(x * 0.7 + 3, z * 0.7 + 8);
