    const n1 = vnoise(x * 3.1, z * 3.1), n2 = vnoise(x * 0.7 + 3, z * 0.7 + 8);
    if (dr < 0.42) { const v = 0.19 + n1 * 0.07 + (hash2(Math.floor(x * 5), Math.floor(z * 5)) - 0.5) * 0.05; c.setRGB(v * 0.95, v, v * 1.12); }
