const fs = require('fs');
const { evalGenome } = require('./evalw.js');
const g = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const n = +(process.argv[3] || 100), base = +(process.argv[4] || 90000);
const tpl = process.argv[5] || __dirname + '/strat_t.js';
const seeds = []; for (let i = 0; i < n; i++) seeds.push(base + i);
const t0 = Date.now();
const r = evalGenome(tpl, g, seeds, 12020 * 3);
