const sd = Math.sqrt(r.reduce((a, b) => a + (b - mean) ** 2, 0) / r.length);
console.log('n', n, 'mean', mean.toFixed(3), 'sd', sd.toFixed(2), 'min', Math.min(...r), 'max', Math.max(...r), 'ms', Date.now() - t0);

