const fs = require('fs');
const { stratFactory, rampartSimulate } = require('./evalw.js');
const g = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const cs = stratFactory(process.argv[3] || __dirname + '/strat_t.js', g);
const leaks = {}, falls = [];
for (let s = 7000; s < 7060; s++) {
  const lk = [];
  const rec = { wave() {}, tick() {}, shot() {}, kill() {}, heal() {}, fall(t, w) { falls.push(w); }, leak(t, e, hp) { lk.push(e.type + '@w' + e.wave); } };
  rampartSimulate(cs, s, 12020 * 3, rec);
  for (const l of lk) { const ty = l.split('@')[0]; leaks[ty] = (leaks[ty] || 0) + 1; }
}
console.log('leaks by type over 60 seeds', JSON.stringify(leaks), 'mean fall wave', falls.reduce((a, b) => a + b) / falls.length);
// final build for one seed
const st = cs(); const s0 = rampartSimulate(cs, 7000, 12020 * 3);
console.log('score', s0.score);
const board = {};
rampartSimulate(() => { const real = cs(); return { plan(s) { const a = real.plan(s); board.last = s.slots.map((x) => x.turret ? x.turret.type[0] + x.turret.tier : '--').join(' '); board.wave = s.wave; board.gold = s.gold; return a; }, target: real.target }; }, 7000, 12020 * 3);
console.log('board at last plan (wave ' + board.wave + ', gold ' + board.gold + '):', board.last);

