function createStrategy() {
  var G = /*G*/{"steps":[[3,3,1],[6,2,1],[7,0,1],[4,0,1],[11,0,1],[13,0,1],[8,0,1],[3,3,2]],"tm":[0,0,0,0,0],"look":1}/*G*/;
  var TYPES = ['bolt', 'cannon', 'frost', 'lance', 'flak'];
  var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
  var DMG = { bolt: 26, cannon: 60, frost: 10, lance: 180, flak: 40 };
  var SPL = { bolt: 0, cannon: 90, frost: 0, lance: 0, flak: 70 };
  var TIDX = { bolt: 0, cannon: 1, frost: 2, lance: 3, flak: 4 };
  return {
    plan: function (state) {
      var acts = [], gold = state.gold, cur = [], i, s;
      for (i = 0; i < 16; i++) cur.push(state.slots[i].turret ? { type: state.slots[i].turret.type, tier: state.slots[i].turret.tier, spent: state.slots[i].turret.spent } : null);
      var look = G.look || 1, seen = 0;
      for (var k = 0; k < G.steps.length && acts.length < 30; k++) {
        s = G.steps[k];
        var slot = s[0], type = TYPES[s[1]], want = s[2], t = cur[slot];
        if (t && t.type === type && t.tier >= want) continue;
        seen++;
        if (seen > look) break;
        var base = COST[type];
        if (t && t.type !== type) {
          var refund = Math.floor(t.spent * 70 / 100);
          if (gold + refund < base) continue;
          gold += refund; acts.push({ op: 'sell', slot: slot }); cur[slot] = t = null;
        }
        if (!t) {
          if (gold < base) continue;
          gold -= base; acts.push({ op: 'build', slot: slot, type: type }); cur[slot] = t = { type: type, tier: 1, spent: base };
        }
        while (t.tier < want) {
          var c = base * (t.tier === 1 ? 1 : 2);
          if (gold < c) break;
          gold -= c; t.tier++; t.spent += c; acts.push({ op: 'upgrade', slot: slot });
        }
        if (t.tier < want) continue; // could not finish; counts as seen
        seen--; // completed: does not consume look window
      }
      return acts;
    },
    target: function (tur, c) {
      var mode = G.tm[TIDX[tur.type]];
      if (!mode || c.length < 2) return -1;
      var best = null, bs = -1e18, i, j, e, v;
      var dmg = DMG[tur.type];
      for (i = 0; i < tur.tier - 1; i++) dmg = Math.floor(dmg * 16 / 10);
      for (i = 0; i < c.length; i++) {
        e = c[i];
        switch (mode) {
          case 1: v = e.hp; break;
          case 2: v = -e.hp; break;
          case 3: v = e.armor * 100000 - e.remaining; break;
          case 4: v = -((e.x - tur.x) * (e.x - tur.x) + (e.y - tur.y) * (e.y - tur.y)); break;
          case 5:
            v = 0;
            for (j = 0; j < c.length; j++) { var dx = c[j].x - e.x, dy = c[j].y - e.y; if (dx * dx + dy * dy <= SPL[tur.type] * SPL[tur.type]) v += 1000; }
            v -= e.remaining / 10;
            break;
          case 6: v = (e.type === 'mender' ? 3e6 : e.type === 'splitter' ? 2e6 : 0) - e.remaining; break;
          case 7: v = (e.slowed > 0 ? 0 : 1e6) - e.remaining; break;
          case 8: v = e.remaining; break;
          case 9: { var dd = tur.type === 'lance' ? dmg : Math.max(1, dmg - e.armor); v = (e.hp <= dd ? 1e6 : 0) - e.remaining; break; }
          case 10: v = e.maxHp - e.remaining / 1000; break;
          default: v = 0;
        }
        if (v > bs) { bs = v; best = e; }
      }
      return best ? best.id : -1;
    }
  };
}

