          case 7: v = (e.slowed > 0 ? 0 : 1e6) - e.remaining; break;
          case 8: v = e.remaining; break;
          case 9: { var dd = tur.type === 'lance' ? dmg : Math.max(1, dmg - e.armor); v = (e.hp <= dd ? 1e6 : 0) - e.remaining; break; }
          case 10: v = e.maxHp - e.remaining / 1000; break;
          default: v = 0;
        }
        if (v > bs) { bs = v; best = e; }
      }
      return best ? best.id : -1;
    }
  };
}

