// steepest-ascent polish over single-edit neighbourhood. usage: polish.js in.json out.json iters nseed
const { Worker } = require('worker_threads');
const fs = require('fs'), path = require('path');
const TPL = path.join(__dirname, 'strat_t.js');
const IN = process.argv[2], OUT = process.argv[3], ITERS = +(process.argv[4] || 20), NSEED = +(process.argv[5] || 64);
const NW = 10;
const workers = [], free = [], waiting = [];
for (let i = 0; i < NW; i++) {
  const w = new Worker(path.join(__dirname, 'evalw.js'));
  w.on('message', (m) => { const cb = w.cb; w.cb = null; free.push(w); pump(); cb(m); });
  workers.push(w); free.push(w);
}
function pump() { while (free.length && waiting.length) { const w = free.pop(); const j = waiting.shift(); w.cb = j.cb; w.postMessage(j.msg); } }
let jid = 0;
const evalAsync = (genome, seeds) => new Promise((res) => { waiting.push({ msg: { id: jid++, tpl: TPL, genome, seeds }, cb: (m) => res(m.scores) }); pump(); });
const mean = (a) => a.reduce((x, y) => x + y, 0) / a.length;
const clone = (g) => JSON.parse(JSON.stringify(g));
function neighbours(g) {
  const out = [];
  const S = g.steps;
  for (let i = 0; i < S.length; i++) {
    for (let s = 0; s < 16; s++) if (s !== S[i][0]) { const n = clone(g); n.steps[i][0] = s; out.push(n); }
    for (let t = 0; t < 5; t++) if (t !== S[i][1]) { const n = clone(g); n.steps[i][1] = t; out.push(n); }
    for (let t = 1; t <= 3; t++) if (t !== S[i][2]) { const n = clone(g); n.steps[i][2] = t; out.push(n); }
    { const n = clone(g); n.steps.splice(i, 1); out.push(n); }
    for (const d of [-1, 1, -3, 3]) { const j = i + d; if (j >= 0 && j < S.length) { const n = clone(g); const x = n.steps.splice(i, 1)[0]; n.steps.splice(j, 0, x); out.push(n); } }
  }
  for (let k = 0; k < 5; k++) for (let m = 0; m < 11; m++) if (m !== g.tm[k]) { const n = clone(g); n.tm[k] = m; out.push(n); }
  for (let l = 1; l <= 4; l++) if (l !== g.look) { const n = clone(g); n.look = l; out.push(n); }
  return out;
}
(async () => {
  let cur = JSON.parse(fs.readFileSync(IN, 'utf8'));
  let base = 20000;
  for (let it = 0; it < ITERS; it++) {
    const seeds = []; for (let i = 0; i < NSEED; i++) seeds.push(base + i); base += NSEED;
    const cs = mean(await evalAsync(cur, seeds));
    const nb = neighbours(cur);
    const t0 = Date.now();
    const sc = await Promise.all(nb.map((n) => evalAsync(n, seeds).then(mean)));
    let bi = -1, bs = cs + 0.02;
    for (let i = 0; i < nb.length; i++) if (sc[i] > bs) { bs = sc[i]; bi = i; }
    console.log('iter', it, 'cur', cs.toFixed(3), 'neighbours', nb.length, 'best', bs.toFixed(3), bi >= 0 ? 'accept' : 'none', ((Date.now() - t0) / 1000).toFixed(0) + 's');
    if (bi < 0) continue;
    cur = nb[bi]; fs.writeFileSync(OUT, JSON.stringify(cur));
  }
  fs.writeFileSync(OUT, JSON.stringify(cur));
  console.log('done'); process.exit(0);
})();

